227	    /**
228	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
229	     * The address is normalized in place (so a required-field check that follows rejects an
230	     * address blank after normalization), the required fields are checked, the telephone and
231	     * email are normalized in place, and the resulting telephone is rejected when it already
232	     * belongs to another owner. Each rule
233	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
234	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
235	     * to be mapped and saved.
236	     *
237	     * @param ownerFieldsDto the submitted owner fields, normalized in place
238	     */
239	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto, LocalDate registrationDate) {
240	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
241	        validateRequiredFields(ownerFieldsDto);
242	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
243	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
244	        rejectDuplicateTelephone(ownerFieldsDto.getTelephone());
245	        rejectDuplicateHousehold(ownerFieldsDto);
246	        rejectCityAtCapacity(ownerFieldsDto.getCity());
247	        rejectDailyLimitExceeded(registrationDate);
248	    }
249	
250	    /**
251	     * Determines the effective registration date for a newly submitted owner, adjusted so it always
252	     * falls on a business day. The date supplied on the request is used when present, otherwise the
253	     * server's current date is used. When that effective date lands on a Saturday or Sunday it is
254	     * rolled forward to the following Monday; a weekday is left unchanged. This single adjusted date
255	     * is what gets stored as {@code registrationDate} and is what every value derived from it (the
256	     * membership number's year segment, the per-day create limit) is computed against.
257	     *
258	     * @param ownerFieldsDto the submitted owner fields, which may carry a registration date
259	     * @return the effective registration date rolled forward to the next business day
260	     */
261	    private LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
262	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
263	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
264	        return toBusinessDay(effective);
265	    }
266	
267	    /**
268	     * Rolls a date forward to the next business day: a Saturday or Sunday is advanced to the
269	     * following Monday, while a weekday is returned unchanged.
270	     *
271	     * @param date the date to adjust
272	     * @return the same date when it is a weekday, otherwise the next Monday
273	     */
274	    private LocalDate toBusinessDay(LocalDate date) {
275	        java.time.DayOfWeek day = date.getDayOfWeek();
276	        if (day == java.time.DayOfWeek.SATURDAY || day == java.time.DayOfWeek.SUNDAY) {
277	            return date.with(java.time.temporal.TemporalAdjusters.next(java.time.DayOfWeek.MONDAY));
278	        }
279	        return date;
280	    }
281	
282	    /**
283	     * The maximum number of owners that may be created on a single day. Once this many owners
284	     * already carry today's {@code registrationDate}, no further owner may be created today.
285	     */
286	    private static final long DAILY_OWNER_LIMIT = 100L;
287	
288	    /**
289	     * Rejects a new owner when {@link #DAILY_OWNER_LIMIT} or more owners already carry the given
290	     * adjusted business-day {@code registrationDate}. The count is taken against the same adjusted
291	     * date the new owner would be stored with, so owners are capped per business day. When the limit
292	     * has been reached a {@link DailyOwnerLimitExceededException} is thrown, which the exception
293	     * advice renders as a 429 Too Many Requests response.
294	     *
295	     * @param registrationDate the adjusted business-day registration date of the owner being created
296	     */
297	    private void rejectDailyLimitExceeded(LocalDate registrationDate) {
298	        long count = this.clinicService.findAllOwners().stream()
299	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
300	            .count();
301	        if (count >= DAILY_OWNER_LIMIT) {
302	            throw new DailyOwnerLimitExceededException(registrationDate);
303	        }
304	    }
305	
306	    /**
307	     * The maximum number of owners a single city may hold. Once a city already contains this
308	     * many owners, no further owner may be created in it.
309	     */
310	    private static final long CITY_OWNER_CAPACITY = 50L;
311	
312	    /**
313	     * Rejects a new owner whose city already contains {@link #CITY_OWNER_CAPACITY} or more owners.
314	     * Cities are compared case-insensitively, consistent with how per-city owners are counted
315	     * elsewhere. When the city is at capacity a {@link CityCapacityExceededException} is thrown,
316	     * which the exception advice renders as a 409 Conflict response.
317	     *
318	     * @param city the city of the owner being created
319	     */
320	    private void rejectCityAtCapacity(String city) {
321	        long count = this.clinicService.findAllOwners().stream()
322	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
323	            .count();
324	        if (count >= CITY_OWNER_CAPACITY) {
325	            throw new CityCapacityExceededException(city);
326	        }
327	    }
328	
329	    /**
330	     * Builds the customer code assigned to a newly created owner. The code is formatted as
331	     * {@code '<CITY3>-<LAST3>-<NNNN>'}, where {@code CITY3} is the upper-cased first three letters
332	     * of the owner's city, {@code LAST3} is the upper-cased first three letters of the owner's last
333	     * name and {@code NNNN} is a per-city 4-digit zero-padded sequence equal to one more than the
334	     * number of owners already in that city. For example the seventh owner in {@code 'Springfield'}
335	     * named {@code 'Smith'} is assigned {@code 'SPR-SMI-0007'}.
336	     *
337	     * @param city the owner's city
338	     * @param lastName the owner's last name
339	     * @return the formatted customer code
340	     */
341	    private String nextCustomerCode(String city, String lastName) {
342	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
343	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
344	        long sequence = this.clinicService.findAllOwners().stream()
345	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
346	            .count() + 1L;
347	        return String.format("%s-%s-%04d", city3, last3, sequence);
348	    }
349	
350	    /**
351	     * Counts the existing owners that share the given {@code firstName} and {@code lastName}
352	     * with the owner being created, compared case-insensitively. The count is taken before the
353	     * new owner is persisted, so it reflects only pre-existing owners and never includes the new
354	     * owner itself. The resulting value is stored on the owner and exposed as {@code namesakeCount}.
355	     *
356	     * @param firstName the first name of the owner being created
357	     * @param lastName the last name of the owner being created
358	     * @return the number of pre-existing owners sharing the same first and last name
359	     */
360	    private int countNamesakes(String firstName, String lastName) {
361	        return (int) this.clinicService.findAllOwners().stream()
362	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
363	                && lastName.equalsIgnoreCase(existing.getLastName()))
364	            .count();
365	    }
