367	    /**
368	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
369	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
370	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
371	     * the names of every offending field, which the exception advice renders as a 400 response
372	     * with an {@code errors} array.
373	     *
374	     * @param ownerFieldsDto the submitted owner fields
375	     */
376	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
377	        List<String> missing = new ArrayList<>();
378	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
379	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
380	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
381	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
382	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
383	        if (!missing.isEmpty()) {
384	            throw new RequiredFieldsMissingException(missing);
385	        }
386	    }
387	
388	    private void addIfBlank(List<String> missing, String fieldName, String value) {
389	        if (value == null || value.isBlank()) {
390	            missing.add(fieldName);
391	        }
392	    }
393	
394	    /**
395	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
396	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
397	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
398	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
399	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
400	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
401	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
402	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
403	     *
404	     * @param telephone the submitted telephone value
405	     * @return the normalized E.164 telephone
406	     */
407	    private String normalizeTelephone(String telephone) {
408	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
409	        String e164;
410	        if (cleaned.startsWith("+")) {
411	            e164 = "+" + cleaned.substring(1);
412	        } else {
413	            String national = cleaned;
414	            if (national.startsWith("0")) {
415	                national = national.substring(1);
416	            }
417	            e164 = "+61" + national;
418	        }
419	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
420	            throw new InvalidFieldsException(List.of("telephone"));
421	        }
422	        return e164;
423	    }
424	
425	    /**
426	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
427	     * and a domain containing at least one dot, none of the parts holding whitespace or a
428	     * second {@code @}.
429	     */
430	    private static final java.util.regex.Pattern EMAIL_PATTERN =
431	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
432	
433	    /**
434	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
435	     * accepted and returned unchanged. When present it must be a syntactically valid address;
436	     * the value is stored and returned lower-cased. When present but invalid an
437	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
438	     * response naming the {@code email} field.
439	     *
440	     * @param email the submitted email value, or {@code null} when omitted
441	     * @return the lower-cased email, or {@code null} when none was supplied
442	     */
443	    private String normalizeEmail(String email) {
444	        if (email == null) {
445	            return null;
446	        }
447	        String trimmed = email.trim();
448	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
449	            throw new InvalidFieldsException(List.of("email"));
450	        }
451	        return trimmed.toLowerCase(java.util.Locale.ROOT);
452	    }
453	
454	    /**
455	     * Rejects a new owner whose normalized telephone is already used by any existing owner.
456	     * The telephone is stored in its normalized E.164 form, so a plain equality check
457	     * against every owner's telephone compares E.164 values. When a match is found a
458	     * {@link DuplicateTelephoneException} is thrown, which the exception advice renders as a
459	     * 409 Conflict response.
460	     *
461	     * @param telephone the normalized telephone of the owner being created
462	     */
463	    private void rejectDuplicateTelephone(String telephone) {
464	        boolean taken = this.clinicService.findAllOwners().stream()
465	            .anyMatch(existing -> telephone.equals(existing.getTelephone()));
466	        if (taken) {
467	            throw new DuplicateTelephoneException(telephone);
468	        }
469	    }
470	
471	    /**
472	     * Rejects a new owner whose {@code lastName} and {@code address} already belong to another
473	     * owner, i.e. one that shares its household (see {@link #findHouseholdMate(String, String)}
474	     * for how that identity is compared). A request may bypass this rule by setting
475	     * {@code sharesHousehold} to {@code true}, allowing several owners to share one household.
476	     * When a household mate is found and the request did not opt in a
477	     * {@link DuplicateHouseholdException} is thrown, which the exception advice renders as a 409
478	     * Conflict response.
479	     *
480	     * @param ownerFieldsDto the submitted owner fields
481	     */
482	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
483	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
484	            return;
485	        }
486	        boolean taken = findHouseholdMate(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress()).isPresent();
487	        if (taken) {
488	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
489	        }
490	    }
491	
492	    /**
493	     * Assigns the shared {@code householdId} for an owner created with {@code sharesHousehold}
494	     * set to {@code true}. The identifier is derived deterministically from the owner's
495	     * household identity (its {@code lastName} and {@code address}, see
496	     * {@link #householdIdFor(String, String)}), so every owner in the same household resolves to
497	     * the same stable value. The new owner receives that value, and any existing household mates
498	     * that do not yet carry it are updated so the whole household shares one identifier. When the
499	     * request did not opt in the owner is left without a household identifier.
500	     *
501	     * @param owner the newly created owner, mutated in place with its household identifier
502	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
503	     */
504	    private void assignHousehold(Owner owner, OwnerFieldsDto ownerFieldsDto) {
505	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
506	            return;
507	        }
508	        String householdId = householdIdFor(owner.getLastName(), owner.getAddress());
509	        owner.setHouseholdId(householdId);
510	        for (Owner mate : findHouseholdMates(owner.getLastName(), owner.getAddress())) {
511	            if (!householdId.equals(mate.getHouseholdId())) {
512	                mate.setHouseholdId(householdId);
513	                this.clinicService.saveOwner(mate);
514	            }
515	        }
516	    }
517	
518	    /**
519	     * Derives the stable {@code householdId} shared by every owner in the household identified by
520	     * the given {@code lastName} and {@code address}. The two fields are normalized exactly as
521	     * household identity is compared elsewhere (case-insensitively, with collapsed whitespace) and
522	     * hashed with SHA-256, so any two owners in the same household — regardless of creation order —
523	     * resolve to the same identifier. The result is formatted as {@code 'HH-<16 hex chars>'}.
524	     *
525	     * @param lastName the household's last name
526	     * @param address the household's address
527	     * @return the deterministic household identifier
528	     */
529	    private String householdIdFor(String lastName, String address) {
530	        String key = collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|"
531	            + normalizeAddress(address).toLowerCase(java.util.Locale.ROOT);
532	        try {
533	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
534	                .digest(key.getBytes(java.nio.charset.StandardCharsets.UTF_8));
535	            StringBuilder sb = new StringBuilder();
536	            for (int i = 0; i < 8; i++) {
537	                sb.append(String.format("%02X", digest[i]));
538	            }
539	            return "HH-" + sb;
540	        }
541	        catch (java.security.NoSuchAlgorithmException e) {
542	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
543	        }
544	    }
545	
546	    /**
547	     * Finds an existing owner that shares a household with the given {@code lastName} and
548	     * {@code address}. When several owners match, the first one encountered is returned.
549	     *
550	     * @param lastName the last name to match on
551	     * @param address the address to match on
552	     * @return the first owner sharing the household, or empty when none exists
553	     */
554	    private Optional<Owner> findHouseholdMate(String lastName, String address) {
555	        return findHouseholdMates(lastName, address).stream().findFirst();
556	    }
557	
558	    /**
559	     * Finds every existing owner that shares a household with the given {@code lastName} and
560	     * {@code address}. Both fields are compared case-insensitively and with runs of whitespace
561	     * collapsed to a single space (and surrounding whitespace trimmed), so for example
562	     * {@code "Franklin"} at {@code "110  W. Liberty St."} matches {@code "franklin"} at
563	     * {@code "110 W. Liberty St."}. This is the single definition of household identity shared by
564	     * every rule that reasons about households.
565	     *
566	     * @param lastName the last name to match on
567	     * @param address the address to match on
568	     * @return the owners sharing the household, in encounter order (possibly empty)
569	     */
570	    private List<Owner> findHouseholdMates(String lastName, String address) {
571	        String normalizedLastName = collapseWhitespace(lastName);
572	        String normalizedAddress = normalizeAddress(address);
573	        return this.clinicService.findAllOwners().stream()
574	            .filter(existing -> normalizedLastName.equalsIgnoreCase(collapseWhitespace(existing.getLastName()))
575	                && normalizedAddress.equalsIgnoreCase(normalizeAddress(existing.getAddress())))
576	            .toList();
577	    }
578	
579	    /**
580	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
581	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
582	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
583	     *
584	     * @param value the value to collapse, or {@code null}
585	     * @return the whitespace-collapsed value, never {@code null}
586	     */
587	    private String collapseWhitespace(String value) {
588	        if (value == null) {
589	            return "";
590	        }
591	        return value.trim().replaceAll("\\s+", " ");
592	    }
593	
594	    /**
595	     * Common street-type abbreviations expanded during address normalization, keyed by their
596	     * upper-cased token.
597	     */
598	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
599	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
600	
601	    /**
602	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
603	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
604	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
605	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
606	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
607	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
608	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
609	     * everywhere an address is stored or compared.
610	     *
611	     * @param address the submitted address value, or {@code null}
612	     * @return the normalized address, never {@code null}
613	     */
614	    private String normalizeAddress(String address) {
615	        if (address == null) {
616	            return "";
617	        }
618	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
619	        if (collapsed.isEmpty()) {
620	            return "";
621	        }
622	        String[] tokens = collapsed.split(" ");
623	        StringBuilder sb = new StringBuilder(collapsed.length());
624	        for (int i = 0; i < tokens.length; i++) {
625	            if (i > 0) {
626	                sb.append(' ');
627	            }
628	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
629	        }
630	        return sb.toString();
631	    }
632	}
